#version 330 core
out vec4 FragColor;
in vec2 fragCoord;

uniform vec2 iResolution;
uniform float iTime;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform vec3 uColor4;

// Terrain generation
float snoise(vec2 p) {
    vec2 f = fract(p);
    p = floor(p);
    float v = p.x + p.y * 1000.0;
    vec4 r = vec4(v, v + 1.0, v + 1000.0, v + 1001.0);
    r = fract(100000.0 * sin(r * 0.001));
    f = f * f * (3.0 - 2.0 * f);
    return 2.0 * (mix(mix(r.x, r.y, f.x), mix(r.z, r.w, f.x), f.y)) - 1.0;
}

float noise(in vec2 uv) {
    return sin(uv.x) + cos(uv.y);
}

float terrain(in vec2 uv, int octaves) {
    float value = 0.0;
    float amplitude = 2.0 / 3.0;
    float freq = 0.5;
    float n1 = 0.0;

    for (int i = 0; i < octaves; i++) {
        n1 = (noise((uv) * freq) - n1);
        value = (value + n1 * amplitude);
        freq *= 2.0 - amplitude;
        amplitude *= 1.0 / 3.0;
        uv = uv.yx - n1 / freq;
    }
    return value;
}

vec2 map(vec3 p, int octaves) {
    float dMin = 28.0;
    float d;
    float mID = -1.0;

    float h = terrain(p.xz, octaves);
    d = p.y - h;
    if (d < dMin) {
        dMin = d;
        mID = 0.0;
    }

    return vec2(dMin, mID);
}

vec2 castRay(vec3 ro, vec3 rd, int octaves) {
    const float p = 0.001;
    float t = 0.0;
    float h = p * 2.0;
    float m = -1.0;
    for (int i = 0; i < 36; i++) {
        if (abs(h) <= p || t >= 28.0) break;
        t += h;
        vec2 res = map(ro + rd * t, octaves);
        h = res.x;
        m = res.y;
    }
    if (t > 28.0) m = -1.0;
    return vec2(t, m);
}

vec3 calcNormal(vec3 p, int octaves) {
    const vec3 eps = vec3(0.002, 0.0, 0.0);
    return normalize(vec3(
        map(p + eps.xyy, octaves).x - map(p - eps.xyy, octaves).x,
        map(p + eps.yxy, octaves).x - map(p - eps.yxy, octaves).x,
        map(p + eps.yyx, octaves).x - map(p - eps.yyx, octaves).x
    ));
}

float shadows(vec3 ro, vec3 rd, float tMax, float k, int octaves) {
    float res = 1.0;
    float t = 0.1;
    for (int i = 0; i < 22; i++) {
        if (t >= tMax) break;
        float h = map(ro + rd * t, octaves).x;
        res = min(res, k * h / t);
        t += h;
    }
    return clamp(res, 0.2, 1.0);
}

vec3 render(vec3 ro, vec3 rd) {
    const int geoLOD = 4;

    vec2 res = castRay(ro, rd, geoLOD);

    vec3 lPos = normalize(vec3(1.0, 0.5, 0.0));
    vec3 lCol = mix(uColor1, uColor2, 0.5);

    vec3 pos = ro + rd * res.x;

    // Sky color - blend between dark colors
    vec3 color = mix(uColor3, uColor4, 0.7);
    float sun = clamp(dot(rd, lPos), 0.0, 1.0);
    color += lCol * 0.3 * sun * sun;

    if (res.y < -0.5) {
        return color;
    }

    vec3 skyColor = color;

    int norLOD = int(max(2.0, 12.0 - 11.0 * res.x / 28.0));
    vec3 nor = calcNormal(pos, norLOD);

    // Mountain coloring with Polinex theme - ENHANCED
    if (res.y > -0.5 && res.y < 0.5) {
        // Base color from uColor palette with more contrast
        color = mix(uColor4 * 1.2, uColor2 * 1.5, step(0.85, nor.y));

        // Layer noise with more variation
        float n = 0.5 * (snoise(pos.xy * vec2(2.0, 15.0)) + 1.0);
        color = mix(uColor3 * 1.3, color, n * smoothstep(0.0, 0.7, 1.0 - nor.y));

        // Stronger highlights on peaks
        color = mix(color, uColor1 * 2.0, smoothstep(0.0, 0.3, nor.y - 0.75));

        // Add depth through gradient
        float heightGrad = pos.y / 5.0;
        color = mix(color * 0.7, color, clamp(heightGrad, 0.0, 1.0));
    }

    // Enhanced lighting for more depth
    float lAmb = clamp(0.6 + 0.6 * nor.y, 0.0, 1.0);
    float lDif = clamp(dot(nor, lPos), 0.0, 2.5);

    if (lDif > 0.05) lDif *= shadows(pos, lPos, 8.0, 12.0, geoLOD);

    color += (0.5 * lAmb) * lCol;
    color *= (2.2 * lDif) * lCol;

    // Fog
    float fog = exp(-0.003 * res.x * res.x);
    color = mix(skyColor, color, fog);

    return color;
}

void main() {
    vec2 pos = 2.0 * (fragCoord.xy / iResolution.xy) - 1.0;
    pos.x *= iResolution.x / iResolution.y;
    float t1 = iTime;

    // Camera
    float x = 0.0 + (0.5 * t1);
    float y = 0.0;
    float z = 0.0 + sin(0.1 * t1);
    vec3 cPos = vec3(x, y, z);
    cPos.y = terrain(cPos.xz, 1) + 2.5;

    const vec3 cUp = vec3(0.0, 1.0, 0.0);
    vec3 cLook = vec3(cPos.x + 1.0, cPos.y * 0.85, 0.0);

    // Camera matrix
    vec3 ww = normalize(cLook - cPos);
    vec3 uu = normalize(cross(ww, cUp));
    vec3 vv = normalize(cross(uu, ww));

    vec3 rd = normalize(pos.x * uu + pos.y * vv + 2.0 * ww);

    // Render
    vec3 color = render(cPos, rd);

    FragColor = vec4(color, 1.0);
}
